"""Supply named WETH positions once, with optional timed withdrawal."""

from almanak_v3 import dashboard as ui
from almanak_v3.caip import AssetType
from almanak_v3.lending import Decision, DecisionInput, LendingConfig, Memory, OutcomeInput
from almanak_v3.lending_intents import SupplyIntent


def validate_config(config: LendingConfig) -> None:
    for allocation in config.allocations:
        chain = allocation.reserve.chain.chain_id
        weth = AssetType(f"{chain}/erc20:0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2")
        if allocation.reserve.asset != weth:
            raise ValueError(f"{allocation.name}: this strategy requires the WETH reserve")


def decide(context: DecisionInput) -> Decision:
    observations = {item.allocation: item for item in context.observations}
    owned = {item.target.allocation: item.shares for item in context.owned}
    supplied_at = context.memory.values.get("supplied_at", {})
    for allocation in context.config.allocations:
        observed = observations[allocation.name]
        intent = decide_allocation(context, allocation, observed, owned, supplied_at)
        if intent is not None:
            return Decision(memory=context.memory, intent=intent)
    return Decision(memory=context.memory)


def decide_allocation(context, allocation, observed, owned, supplied_at):
    name = allocation.name
    started = supplied_at.get(name)
    if context.teardown or withdrawal_due(allocation, observed, started):
        return close_allocation(context, allocation, observed, owned[name])
    if started is None:
        return context.config.supply(name, allocation.amount)
    return None


def withdrawal_due(allocation, observed, started):
    return (
        started is not None
        and allocation.hold_seconds is not None
        and observed.position.reserve.block.timestamp >= started + allocation.hold_seconds
    )


def close_allocation(context, allocation, observed, shares):
    if shares or observed.allowance:
        return context.config.withdraw(allocation.name)
    return None


def on_outcome(context: OutcomeInput) -> Memory:
    result = context.result
    if not (result.success and result.complete and isinstance(result.intent, SupplyIntent)):
        return context.memory
    previous = context.memory.values.get("supplied_at", {})
    if not isinstance(previous, dict):
        raise ValueError("supplied_at memory must map allocation names to block times")
    supplied_at = dict(previous)
    supplied_at[result.intent.target.allocation] = result.block.timestamp
    return Memory(
        version=context.memory.version,
        values={**context.memory.values, "supplied_at": supplied_at},
    )


def dashboard(ctx: ui.Context) -> ui.Dashboard:
    return ui.Dashboard(
        title="Aave WETH supply",
        description="Named WETH positions, holding rules and recorded on-chain outcomes.",
        blocks=(
            ui.Group(
                id="overview",
                title="Position overview",
                blocks=(
                    ui.Metric(
                        id="open-positions",
                        label="Positions with owned shares",
                        value=ctx.values["position-count"],
                    ),
                    *tuple(
                        ui.Metric(
                            id=f"{p.allocation}-balance",
                            label=p.allocation.replace("_", " "),
                            value=ctx.values[f"{p.allocation}-observed"],
                        )
                        for p in ctx.positions
                    ),
                ),
            ),
            ui.Table(
                id="positions", title="Supply positions", data=ctx.datasets["supply_positions"]
            ),
            *tuple(allocation_dashboard(ctx, p) for p in ctx.positions),
            ui.Table(id="gas", title="Fund costs", data=ctx.datasets["fund_costs"]),
            ui.Table(id="activity", title="Transaction history", data=ctx.datasets["transactions"]),
            ui.Text(
                id="policy",
                text="Each allocation supplies once. Its holding period starts at "
                "the confirmed supply block recorded in strategy memory. Teardown closes the "
                "remaining owned shares and clears allowances. Token deltas exclude gas costs.",
            ),
        ),
    )


def allocation_dashboard(ctx: ui.Context, position: ui.Position) -> ui.Group:
    name = position.allocation
    return ui.Group(
        id=f"allocation-{name}",
        title=name.replace("_", " "),
        blocks=(
            ui.BarChart(
                id=f"flows-{name}",
                title="Recorded capital movements",
                points=(
                    ui.Point(label="Supplied", value=ctx.values[f"{name}-supplied"]),
                    ui.Point(label="Withdrawn", value=ctx.values[f"{name}-withdrawn"]),
                ),
                caption="Confirmed asset effects in this allocation. "
                "Withdrawals include any realized accrual.",
            ),
            ui.Metric(id=f"owned-{name}", label="Owned supply shares", value=position.owned_shares),
            ui.Metric(
                id=f"delta-{name}", label="Closed token delta", value=ctx.values[f"{name}-delta"]
            ),
        ),
    )
